my $source = <<'ISF';
(actor samples
  (types
    (type leaf (record (count (four_state (signed (bits 3)))) (ready (two_state bit))))
    (type frame (record (tag (bits 2)) (nested leaf) (lanes (list bit (bits 2)))))
    (type alias frame))
  (enums (mode (BUSY 1)))
  (interface (input start) (input mode) (output seen (width 3)) (output done))
