sub refuses {
    my ($run, $pattern, $name) = @_;
    my $ok = eval {$run->(); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$name refuses");
    like($line // '', $pattern, "$name names the first-line cause");
}
sub render {
    my ($value) = @_;
    return ref($value) eq 'ARRAY' ? '(' . join(' ', map {render($_)} @$value) . ')' : $value;
}

subtest 'independent packed-layout and scalar-property witnesses' => sub {
